// 答えは console.log で出力する
// ここに解答を書く

solution.code:
import { readFileSync } from "fs";

const [first, second] = readFileSync(0, "utf8").trim().split("\n");
const [n, k] = first.split(" ").map(Number);
const a = second.split(" ").map(Number);

// N ≤ 2000 なので、すべての組を調べても約 200 万回で済む
let count = 0;
for (let i = 0; i < n; i++) {
  for (let j = i + 1; j < n; j++) {
    if (a[i] + a[j] === k) count++;
  }
}
console.log(count);
